/* native_bench.c - time xlisp_eval() of a file, same wrapper as the WASM build */
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>
#include "native_wrapper.c" /* generated by build.sh from $XLISP_DIR/wasm_wrapper.c */

static double now_ms(void) {
    struct timespec ts; clock_gettime(CLOCK_MONOTONIC, &ts);
    return ts.tv_sec * 1000.0 + ts.tv_nsec / 1e6;
}
static int cmp(const void *a, const void *b) { double x = *(double*)a, y = *(double*)b; return (x > y) - (x < y); }

int main(int argc, char **argv) {
    if (argc < 2) { fprintf(stderr, "usage: %s file.lsp [runs]\n", argv[0]); return 1; }
    int runs = argc > 2 ? atoi(argv[2]) : 20;
    FILE *f = fopen(argv[1], "rb"); if (!f) { perror(argv[1]); return 1; }
    fseek(f, 0, SEEK_END); long n = ftell(f); fseek(f, 0, SEEK_SET);
    char *src = malloc(n + 1); fread(src, 1, n, f); src[n] = 0; fclose(f);
    /* xlisp_eval evaluates one form: wrap the file in (begin ...) */
    char *wrapped = malloc(n + 16); sprintf(wrapped, "(begin %s )", src); src = wrapped;
    if (!xlisp_init()) { fprintf(stderr, "init failed\n"); return 1; }
    const char *res = "";
    for (int i = 0; i < 3; i++) res = xlisp_eval(src);
    double *t = malloc(sizeof(double) * runs), sum = 0;
    for (int i = 0; i < runs; i++) { double a = now_ms(); res = xlisp_eval(src); t[i] = now_ms() - a; sum += t[i]; }
    qsort(t, runs, sizeof(double), cmp);
    printf("{\"min\":%.3f,\"median\":%.3f,\"mean\":%.3f,\"result\":\"%s\"}\n", t[0], t[runs/2], sum/runs, res);
    return 0;
}
